// Social-Pip WhatsApp Pre-Send Check
// WhatsApp has HIGH ban risk - be extremely careful
const item = $input.first().json;

// WhatsApp anti-ban limits (very conservative)
const WHATSAPP_MAX_DAILY_NEW = 100;  // New accounts
const WHATSAPP_MAX_DAILY_WARM = 200; // Warmed accounts
const WHATSAPP_MIN_DELAY_MS = 20 * 1000; // 20 seconds
const WHATSAPP_WARMUP_DAYS = 14;

const accountStats = {
  messagesToday: item.messagesToday || 0,
  lastMessageAt: item.lastMessageAt ? new Date(item.lastMessageAt) : null,
  accountStatus: item.accountStatus || 'ACTIVE',
  accountAge: item.accountAge || 0, // days
  warmupProgress: item.warmupProgress || 0
};

const errors = [];

// Determine max daily based on warmup
const maxDaily = accountStats.accountAge < WHATSAPP_WARMUP_DAYS 
  ? WHATSAPP_MAX_DAILY_NEW 
  : WHATSAPP_MAX_DAILY_WARM;

if (accountStats.messagesToday >= maxDaily) {
  errors.push(`Daily limit reached: ${accountStats.messagesToday}/${maxDaily}`);
}

// Enforce delay between messages
if (accountStats.lastMessageAt) {
  const timeSinceLastMsg = Date.now() - accountStats.lastMessageAt.getTime();
  if (timeSinceLastMsg < WHATSAPP_MIN_DELAY_MS) {
    const waitSeconds = Math.ceil((WHATSAPP_MIN_DELAY_MS - timeSinceLastMsg) / 1000);
    errors.push(`Wait ${waitSeconds} more seconds`);
  }
}

// Warmup period strictness
if (accountStats.accountAge < 7) {
  if (accountStats.messagesToday >= 50) {
    errors.push('First week: max 50 messages/day');
  }
}

// Check account status (WhatsApp bans are common)
if (['BANNED', 'RESTRICTED', 'TEMP_BANNED'].includes(accountStats.accountStatus)) {
  errors.push(`Account status: ${accountStats.accountStatus}. WhatsApp may have banned this number.`);
}

if (errors.length > 0) {
  return { json: { valid: false, errors, accountStats } };
}

return { json: { valid: true, message: item, accountStats } };

const result = $input.first().json;

if (result.error) {
  // WhatsApp-specific error handling
  let errorCode = 'UNKNOWN';
  if (result.error.includes('banned')) errorCode = 'E005';
  if (result.error.includes('rate')) errorCode = 'E001';
  if (result.error.includes('not registered')) errorCode = 'E002';

  return {
    json: {
      success: false,
      error: result.error,
      errorCode,
      platform: 'whatsapp'
    }
  };
}

return {
  json: {
    success: true,
    messageId: result.messageId,
    to: result.to,
    publishedAt: new Date().toISOString(),
    platform: 'whatsapp'
  }
};

